#define MT6589_MSDC_MAIN_VER_RESET 0x00000000u

/* 0x0104  ECO_VER - MSDC ECO Version Register  [reset 0x00000000u] */
#define MT6589_MSDC_ECO_VER 0x11230104u
#define MT6589_MSDC_ECO_VER_RESET 0x00000000u
#define MT6589_MSDC_ECO_VER_ECOVER_31_16__SHIFT 16
#define MT6589_MSDC_ECO_VER_ECOVER_31_16__MASK  0xffff0000u
#define MT6589_MSDC_ECO_VER_ECOVER_15_0__SHIFT 0
#define MT6589_MSDC_ECO_VER_ECOVER_15_0__MASK  0x0000ffffu

#define MT6589_MSDC_NUM_REGS 41

